/**
 * The body belongs to a class of grahas under the readings: a benefic, a malefic or a maraka. What a verse names by nature and then narrows, "a malefic, excepting the lords of the 10th and 9th" (BPHS ch. 42 v. 8), binds a graha with `for-any` and asks this of it.
 */
export interface ConditionPlanetIs {
  readonly type: 'planet-is';
  /**
   * Of which class.
   */
  readonly class: GrahaClass;
  /**
   * Who.
   */
  readonly planet: unknown;
}

/**
 * How one body regards another by natural relationship (BPHS ch. 3's naisargika maitri, as the catalogue lists it): a friend, a neutral or an enemy. The relationship is not symmetric — Mercury counts the Sun a friend and the Sun counts Mercury neutral — so it is `of`'s regard for `to`, as "the ascendant lord friendly to the Sun" (BPHS ch. 43 vv. 71 to 73) is the lord's. A body is none of these to itself, and the lagna to anything.
 */
export interface ConditionNaturalRelation {
  readonly type: 'natural-relation';
  /**
   * Whose regard.
   */
  readonly of: unknown;
  /**
   * Which relations meet it.
   */
  readonly relations: readonly Relation[];
  /**
   * For whom.
   */
  readonly to: unknown;
}

/**
 * Two references resolve to one body.
 */
export interface ConditionSameBody {
  readonly type: 'same-body';
  /**
   * The other.
   */
  readonly as: unknown;
  /**
   * One.
   */
  readonly of: unknown;
}

/**
 * The birth stands within so many ghatikas of a limb's edge: the first ghatikas of it, or the last. BPHS ch. 92 measures every gandanta this way, and ch. 9 v. 14 each twilight as the night's edge; a limb the chart does not measure never holds.
 */
export interface ConditionAtLimbEdge {
  readonly type: 'at-limb-edge';
  /**
   * Which end of it.
   */
  readonly edge: Edge;
  /**
   * How many ghatikas of 24 minutes.
   */
  readonly ghatikas: number;
  /**
   * Which limb.
   */
  readonly limb: Limb;
}

/**
 * The birth falls in one of a limb's equal parts, counted from its start: BPHS ch. 87 divides Krishna Chaturdashi into six and reads each part apart. The parts are of the limb's own span, so a long tithi has long parts; a limb the chart does not measure never holds.
 */
export interface ConditionLimbPart {
  readonly type: 'limb-part';
  /**
   * Which limb.
   */
  readonly limb: Limb;
  /**
   * Into how many equal parts it is divided, at least two.
   */
  readonly of: number;
  /**
   * Which of them, the first being 1.
   */
  readonly parts: readonly number[];
}

/**
 * The birth fell by day, between sunrise and sunset; a chart that does not say never holds it, and `not` of it is not "by night" there.
 */
export interface ConditionBirthByDay {
  readonly type: 'birth-by-day';
}

/**
 * The birth's tithi touched no sunrise: it began after the birth day's sunrise and ended before the next, so no day is named by it. This is the avama, or kshaya, tithi BPHS ch. 85 v. 3 lists among the inauspicious births and ch. 88 gives the remedy of (crux C759). A chart that does not say never holds it.
 */
export interface ConditionBirthInKshayaTithi {
  readonly type: 'birth-in-kshaya-tithi';
}

/**
 * The body stands in one of these nakshatras, in one of the padas when the rule names any. It is read from the body's own sidereal longitude, 13°20′ to a nakshatra and a quarter of that to a pada, where `panchanga-nakshatra` reads the one the chart recorded for the Moon.
 */
export interface ConditionPlanetInNakshatra {
  readonly type: 'planet-in-nakshatra';
  /**
   * Which.
   */
  readonly nakshatras: readonly Member<catalogue.Nakshatra>[];
  /**
   * Which padas, 1 to 4; any when none.
   */
  readonly padas?: readonly number[];
  /**
   * Who.
   */
  readonly planet: unknown;
}

/**
 * Two bodies stand in one nakshatra: "the birth star identical with the one in which Ketu rises" (Saravali ch. 10 v. 12).
 */
export interface ConditionSameNakshatra {
  readonly type: 'same-nakshatra';
  /**
   * The other.
   */
  readonly as: unknown;
  /**
   * One.
   */
  readonly of: unknown;
}

/**
 * The body reaches what its measure requires of it: "the ascendant lord is strong" (BPHS ch. 36 vv. 9 to 28). A chart that carries no strength never holds it.
 */
export interface ConditionPlanetStrong {
  readonly type: 'planet-strong';
  /**
   * Who.
   */
  readonly planet: unknown;
}

/**
 * The body falls short of what is required of it. A chart that carries no strength never holds this either, so it is not the `not` of `planet-strong`: on a silent chart both are false, which is the honest answer to both questions.
 */
export interface ConditionPlanetWeak {
  readonly type: 'planet-weak';
  /**
   * Who.
   */
  readonly planet: unknown;
}

/**
 * One body's strength exceeds another's.
 */
export interface ConditionPlanetStrongerThan {
  readonly type: 'planet-stronger-than';
  /**
   * Who.
   */
  readonly planet: unknown;
  /**
   * Than whom.
   */
  readonly than: unknown;
}

/**
 * One reference aspects another by rashi drishti (BPHS ch. 26 vv. 1 to 3): a movable sign aspects the three fixed signs but the one next to it, a fixed sign the three movable but the one before it, and a dual sign the other three dual signs. A body lends the aspect of the sign it stands in, so naming a body names its sign.
 */
export interface ConditionRashiAspects {
  readonly type: 'rashi-aspects';
  /**
   * Who aspects: a sign, a body's sign, or whichever benefic's or malefic's sign does.
   */
  readonly from: unknown;
  /**
   * What is aspected.
   */
  readonly target: unknown;
}

/**
 * An intervention stands on a reference (BPHS ch. 31 vv. 2 to 9): the grahas in the intervening house outnumber those in the house that obstructs it, and there is at least one of them. The nine are counted; from a node the houses are counted backwards, the nodes moving so.
 */
export interface ConditionArgala {
  readonly type: 'argala';
  /**
   * What is intervened on: a sign, or the sign a body stands in.
   */
  readonly on: unknown;
  /**
   * Which intervention, each with the house that obstructs it.
   */
  readonly place: ArgalaPlace;
}

/**
 * Three or more malefics stand in the third from a reference, which the same verses call a contrary intervention, harmless and very favourable; nothing obstructs it.
 */
export interface ConditionVipareetaArgala {
  readonly type: 'vipareeta-argala';
  /**
   * What is intervened on.
   */
  readonly on: unknown;
}

/**
 * The birth falls on a sankranti: on the day, sunrise to sunrise, the Sun enters a sign, or within so many hours of the entry when the rule says. BPHS ch. 90 names each sankranti by its day of the week.
 */
export interface ConditionBirthOnSankranti {
  readonly type: 'birth-on-sankranti';
  /**
   * How many hours either side of the entry; the whole day when unset.
   */
  readonly windowHours?: number | null;
}

/**
 * A graha in transit stands in one of the houses counted from a natal sign: Saturn in the twelfth, first or second from the natal Moon is sade sati, and gochar is counted from the Moon (Phaladeepika ch. 26 v. 1). It reads the sky at an instant an evaluator was given ([`Evaluator::with_transits`](crate::Evaluator::with_transits)) and never holds without one; the transiting graha is not a natal body, so it adds no participant.
 */
export interface ConditionTransitInHouse {
  readonly type: 'transit-in-house';
  /**
   * The natal sign counted from.
   */
  readonly from: unknown;
  /**
   * Which houses, counted from `from`.
   */
  readonly houses: readonly number[];
  /**
   * The graha in transit.
   */
  readonly planet: Member<catalogue.Graha>;
}

/**
 * What a rule says happens when it holds, beyond being present, in the ways its verse says it. The texts count a life in two ways — a span (Phaladeepika ch. 13 v. 6's bands, and Saravali ch. 10's verse-by-verse spans) and a class of life (BPHS ch. 43 vv. 52 to 54: short, medium, long and the rest) — and everywhere else they say what follows in words: a dwigraha verse gives a trade and a temper, not a number. A consumer therefore reads a span or a class where a text gives one and the verse's own statement where it does not, and the SDK invents none of them.
 */
export type RuleOutcome = RuleOutcomeLifeSpan | RuleOutcomeLifeClass | RuleOutcomeEffect;

/**
 * The life span the rule gives, in the unit its verse uses.
 */
export interface RuleOutcomeLifeSpan {
  readonly type: 'life-span';
  /**
   * How many.
   */
  readonly count: number;
  /**
   * Of what.
   */
  readonly unit: Unit;
}

/**
 * The class of life the verse gives, which carries its own span.
 */
export interface RuleOutcomeLifeClass {
  readonly type: 'life-class';
  /**
   * Which class.
   */
  readonly class: LifeClass;
}

/**
 * What the verse says follows, in words: the SDK's own short statement of the reading, not the translator's prose.
 */
export interface RuleOutcomeEffect {
  readonly type: 'effect';
  /**
   * The statement.
   */
  readonly text: string;
}

/**
 * A group of conditions found from one reference point.
 */
export interface RuleGroup {
  /**
   * What must all hold.
   */
  readonly conditions: readonly Condition[];
  /**
   * What a result says it was found from.
   */
  readonly label: string;
  /**
   * The point its houses are counted from, which a house-weighted severity reads: a body's key, or the engine's `lagna`, `moon` or `venus`.
   */
  readonly reference: string;
  /**
   * How much this place counts for a count-based severity; one unless the rule weighs it more.
   */
  readonly weight?: number;
}

/**
 * How grave a present rule is, out of the scale its values use (the engine's is 100).
 */
export type Severity = SeverityFixed | SeverityHouseWeighted | SeverityPlanetStrengthInverse | SeverityCountBased | SeverityKootShortfall;

/**
 * Always this.
 */
export interface SeverityFixed {
  readonly type: 'fixed';
  /**
   * The severity.
   */
  readonly value: number;
}

/**
 * By the house a body stands in counted from each reference the rule was found from, the gravest of them; the default where no weight is given.
 */
export interface SeverityHouseWeighted {
  readonly type: 'house-weighted';
  /**
   * Every other house's.
   */
  readonly default: number;
  /**
   * The body, Mars unless the rule names another (the engine's evaluator reads Mars).
   */
  readonly planet?: string;
  /**
   * Each weighted house's severity.
   */
  readonly weights: Readonly<Record<string, number>>;
}

/**
 * From `min` when the body is exalted or in its own sign to `max` when debilitated, halfway otherwise.
 */
export interface SeverityPlanetStrengthInverse {
  readonly type: 'planet-strength-inverse';
  /**
   * The body.
   */
  readonly basePlanet: string;
  /**
   * When debilitated.
   */
  readonly max: number;
  /**
   * When exalted or in its own sign.
   */
  readonly min: number;
}

/**
 * So much for each place it was found from, by its weight, up to a cap.
 */
export interface SeverityCountBased {
  readonly type: 'count-based';
  /**
   * At most.
   */
  readonly cap: number;
  /**
   * For each.
   */
  readonly perOccurrence: number;
}

/**
 * By how far a matched pair's koota score falls short: without the pair only `full` is known, and that is the severity.
 */
export interface SeverityKootShortfall {
  readonly type: 'koot-shortfall';
  /**
   * With no score at all.
   */
  readonly full: number;
  /**
   * Less for each point the score regains.
   */
  readonly perPointMissing: number;
}

/**
 * Where a rule or a table comes from.
 */
export interface RuleSource {
  /**
   * Its chapter.
   */
  readonly chapter?: string | null;
  /**
   * A note on the reading.
   */
  readonly note?: string | null;
  /**
   * How good the evidence is, when the author says.
   */
  readonly rank?: number | null;
  /**
   * The text.
   */
  readonly text: string;
  /**
   * Its verse.
   */
  readonly verse?: string | null;
}

/**
 * In whose periods a rule gives what it says.
 *
 * `concerned`: In the periods of the grahas that formed it, and in a sign-based dasha of the signs they stand in: "the Rashi or planet concerned" (BPHS ch. 31, ch. 33 vv. 94 to 99). What every rule does unless its verse says otherwise.
 * `throughout`: In every period: the Nabhasa yogas' effects "will be felt throughout, in all the Dasha periods" (BPHS ch. 35 v. 50).
 */
export type Timing = 'concerned' | 'throughout';

/**
 * What the rectification multiplies (v. 46).
 *
 * `class-years`: The class's years once, as vv. 41 to 44 give them.
 * `per-pair`: The class's years once for each pair that gave it, as the translator's example takes 36 years for two pairs as 72.
 */
export type Basis = 'class-years' | 'per-pair';

/**
 * Which way a contributor's degrees rectify the years (v. 45).
 *
 * `remaining`: As the verse says it: a contributor at the start of a sign gives the whole, one at its end nothing, so the degrees still to run count.
 * `elapsed`: As the translator's arithmetic runs: the degrees gone count.
 */
export type YearsRectification = 'remaining' | 'elapsed';

/**
 * What Saturn among the contributors does to the class (v. 47).
 *
 * `lowers`: Lowers it a class, as the verse says first.
 * `raises`: Raises it, as "some advocate".
 */
export type SaturnAmongThem = 'lowers' | 'raises';

/**
 * A graha's motion as v. 15 sorts it (C430).
 *
 * `FAST`: Fast (शीघ्र): it looks to its left.
 * `MEAN`: Mean (मध्य): it looks ahead.
 * `RETROGRADE`: Retrograde (वक्र): it looks to its right.
 */
export type VedhaMotion = 'FAST' | 'MEAN' | 'RETROGRADE';

/**
 * The sixteen vowels in the order v. 3 lays them, a to the visarga.
 *
 * `A`: अ
 * `AA`: आ
 * `I`: इ
 * `II`: ई
 * `U`: उ
 * `UU`: ऊ
 * `RI`: ऋ
 * `RII`: ॠ
 * `LI`: ऌ
 * `LII`: ॡ
 * `E`: ए
 * `AI`: ऐ
 * `O`: ओ
 * `AU`: औ
 * `AM`: अं, the anusvara.
 * `AH`: अः, the visarga.
 */
export type ChakraVowel = 'A' | 'AA' | 'I' | 'II' | 'U' | 'UU' | 'RI' | 'RII' | 'LI' | 'LII' | 'E' | 'AI' | 'O' | 'AU' | 'AM' | 'AH';

/**
 * Which vowels a graha at a corner's juncture strikes (v. 26, C431).
 *
 * `FOUR_VOWELS`: The four on the corner's diagonal, a u ḷ o at the north-east: the tika's tradition (आम्नाय), and the reading Phaladeepika's editor renders.
 * `OUTER_VOWEL`: The outermost alone, a ā i ī, which no line reaches: the tika's "another explanation".
 */
export type CornerVedha = 'FOUR_VOWELS' | 'OUTER_VOWEL';

/**
 * What a graha's front strikes (C429).
 *
 * `STAR_ONLY`: The star at its far end alone, as every worked example lists it (*Jatakabharana* vv. 4–6 and Rajavijaya, quoted under Phaladeepika ch. 26 v. 48; Ranahasti, quoted by the tika on vv. 15–18).
 * `EVERY_CELL`: Every cell it passes, v. 13 read alone.
 */
export type FrontVedha = 'STAR_ONLY' | 'EVERY_CELL';

/**
 * Which of the three lines a graha looks along (C430).
 *
 * `TEXT`: vv. 15 and 19: the five from Mars along one line, by their motion; the Sun, the Moon and the nodes along all three.
 * `ALL_THREE`: Every graha along all three, v. 13 read alone.
 * `ONE_EACH`: The five by their motion, the Sun and the Moon (always fast) to the left, the nodes (always retrograde) to the right: the "some" the tika reports on v. 19.
 */
export type VedhaSight = 'TEXT' | 'ALL_THREE' | 'ONE_EACH';

/**
 * Where the balance a nakshatra year opens with comes from (crux C123).
 *
 * `NATAL_MOON`: What remained of the birth Moon's nakshatra: the same every year. Charak's worked year.
 * `ENTRY_MOON`: How far the Moon at the return is through its own nakshatra: the *Nilakanthi*'s appendix, after the *Hayanaratna*.
 * `WHOLE`: None: the first lord runs its whole share from the return, as the appendix says older almanacs do.
 */
export type MuddaBalance = 'NATAL_MOON' | 'ENTRY_MOON' | 'WHOLE';

/**
 * How a dasha's birth period is divided among its sub-periods.
 *
 * `COMPRESSED`: Each sub-period its share of the balance the birth period runs for, which the recording engine does on every recorded answer.
 * `ELAPSED`: Each sub-period its share of the whole period, which began before birth; those already over are dropped and the one running is cut at birth.
 */
export type BirthPeriod = 'COMPRESSED' | 'ELAPSED';

/**
 * What a unit of the year is (crux C122).
 *
 * `SUN_DEGREES`: The Sun's motion through one degree from where it stood at the return: Charak's definition of the 360 "solar days", and the *Nilakanthi*'s dating. The year ends on the next return.
 * `EVEN`: An equal share of the time from this return to the next: Charak's "spread proportionately".
 * `DAYS`: The whole year as this many civil days from the return: Charak's printed durations, 360 for the Mudda and the Yogini and 365 for the Patyayini. The one clock that needs no ephemeris.
 */
export type YearClock =
  | 'SUN_DEGREES'
  | 'EVEN'
  | { readonly DAYS: number };

/**
 * Venus's house of joy, which the Sthana part is read from.
 *
 * `FIFTH`: The 5th: the *Tajika Nilakanthi*'s verse (*putra*, the house of children) and the source's own.
 * `TWELFTH`: The 12th, as a widely used program reads it: measured over 600 charts by its values alone, where it and this differ in nothing else (`03-design/tajika-harsha.md`).
 */
export type VenusPlace = 'FIFTH' | 'TWELFTH';

/**
 * When a saham is carried one sign further: the source's "essential consideration".
 *
 * `DEGREES`: **When c is not between b and a by degrees**, counted in the order of the signs from b: the default. All seven worked sahams the source prints agree with it, among them a birth chart's Punya where the Sun, the lagna and the Moon all stand in Leo, 3°49′, 14°33′ and 17°08′ — between by degrees and not by signs, and printed without the added sign.
 * `SIGNS`: **When c's sign is not after b's and up to a's**, counted in whole signs, with a and b in one sign counting as the whole circle. What a widely used program applies (measured, not read: `03-design/tajika-sahams.md`); the source's Leo birth chart refutes it, and it is here so that a caller can reproduce what that program prints.
 * `NEVER`: **Never**: a − b + c and nothing more, as the Arabic parts of other traditions are read.
 */
export type AddSign = 'DEGREES' | 'SIGNS' | 'NEVER';

/**
 * Where a house's point stands, for the sahams that read one.
 *
 * `SRIPATI`: **Sripati's mid-points**, the default, and the source's own recipe: the lagna, the midheaven and their opposites are the mid-points of the four kendras, and each quadrant between is trisected. Built from the chart's lagna and midheaven, so it is the source's whatever chalit a profile gives the chart. It reproduces every mid-point the source prints for its Example Chart.
 * `CHALIT`: **The chart's own chalit middles**, under whatever division its profile names — Sripati's too under most, equal houses centred on the lagna under a profile whose chalit is Vehlow's.
 * `EQUAL`: **Equal houses from the lagna**: the house *n* stands (n − 1) × 30° past the lagna's degree — for a caller with no midheaven, and what a program reading only planets and a lagna can do. The source's Chart X-9 prints an eighth mid-point, Capricorn 4°12′ under a lagna of Gemini 7°15′, that no equal division gives.
 */
export type HousePoints = 'SRIPATI' | 'CHALIT' | 'EQUAL';

/**
 * Which of the source's two Roga sahams is meant.
 *
 * `LAGNA`: **Lagna − Moon + lagna**, day and night: the formula the source gives as the saham, and the default.
 * `SATURN`: **Saturn − Moon + lagna**, reversed by night: "according to another authority", and the one the source says it has "found giving better results".
 */
export type RogaReading = 'LAGNA' | 'SATURN';

/**
 * Whose friendship the "friend" and "inimical planet" clauses read.
 *
 * `POSITIONAL`: Tajika's positional friendship, the only one the source defines (ch. VI): friends at houses 3, 5, 9 and 11 from each other, enemies at 1, 4, 7 and 10 — so two planets **in one sign are enemies**, and a saham whose lord sits in its sign has no friend for company.
 * `NATURAL`: The catalogue's natural friendships, which do not move with the chart.
 */
export type SahamFriendship = 'POSITIONAL' | 'NATURAL';

/**
 * Which planets a saham's clauses call benefic and malefic.
 *
 * `CHAPTER`: The chapter's own: the Moon, Mercury, Jupiter and Venus benefic, the Sun, Mars and Saturn malefic — its forty-seventh year calls the Sun "another malefic", its birth Punya is with "all the natural benefics (viz., the Moon, Mercury, Jupiter and Venus)" — the [`BENEFICS`] Kuttha reads, so the two cannot drift apart.
 * `PARASHARI`: The catalogue's Parashari natures, under which Mercury is neither.
 */
export type SahamNatures = 'CHAPTER' | 'PARASHARI';

/**
 * Which readings of the source this module applies.
 */
export interface DrishtiRules {
  /**
   * What a pair less than a degree past is doing.
   */
  readonly subDegree?: SubDegree;
}

/**
 * Whether the Moon may hold the year, and who takes it when it may not.
 *
 * `PASSED_OVER`: It is passed over and the next one down that aspects takes the year; where nobody is next, its **Ithasala successor** does. Charak's two steps, and the default.
 * `ITHASALA`: Its Ithasala successor takes the year at once, with no step down: the *Tajika Nilakanthi*'s own view (Varshatantra v. 12), which Charak gives as "some authorities".
 * `LIKE_ANY_OTHER`: It holds the year like any other office-bearer, for the "extraordinarily strong and well-positioned" Moon the source allows and leaves to the reader.
 */
export type MoonMayRule = 'PASSED_OVER' | 'ITHASALA' | 'LIKE_ANY_OTHER';

/**
 * Which planets may succeed the Moon through an Ithasala.
 *
 * `ANY_PLANET`: Any of the seven, the default: Charak's "the planet with which this Moon establishes an Ithasala", and the *Nilakanthi*'s verse.
 * `OFFICE_BEARER`: Only an office-bearer, as one of the *Nilakanthi*'s two commentaries reads its verse.
 */
export type MoonPartner = 'ANY_PLANET' | 'OFFICE_BEARER';

/**
 * What to do when no office-bearer aspects the annual lagna (crux C106).
 *
 * `MUNTHA_LORD`: The Muntha's lord takes the year: the source's own rule.
 * `ANNUAL_LAGNA_LORD`: The annual lagna's lord takes it, which "some authorities" give.
 * `STRONGEST`: The strongest of the five takes it, aspect or none: the *Tajika Nilakanthi*'s Varshatantra v. 11.
 */
export type NoneAspects = 'MUNTHA_LORD' | 'ANNUAL_LAGNA_LORD' | 'STRONGEST';

/**
 * Who takes the year when the office-bearers tie outright (crux C106).
 *
 * `MUNTHA_LORD`: The Muntha's lord: the source's own rule.
 * `DINA_RATRI_PATI`: The Dina-Ratri Pati, which "still others" give.
 */
export type VarsheshaTied = 'MUNTHA_LORD' | 'DINA_RATRI_PATI';

/**
 * When the Moon is one of the [`BENEFICS`] whose aspect makes a Kuttha.
 *
 * `ALWAYS`: **Always**, the default: Charak's four natural benefics.
 * `WAXING`: **Waxing** only, the bright half: less than 180° ahead of the Sun. The commentary's "full Moon", read as widely as its word allows.
 */
export type MoonBenefic = 'ALWAYS' | 'WAXING';

/**
 * Which of the pair may be the one at a sign's end in a **Tambira**.
 *
 * `KARYESHA`: **The karyesha**, the default: the definition and Table X-3.
 * `EITHER_LORD`: **Either lord**: the "some authorities" of the source's comment.
 */
export type TambiraMover = 'KARYESHA' | 'EITHER_LORD';

/**
 * Where a name in Abhijit's row stands when a koota needs one of the 108 padas (C292).
 *
 * `REFUSE`: Refused, naming this knob: no source read places it.
 * `UTTARA_ASHADHA`: Uttarashadha's 4th pada, which holds most of Abhijit's span.
 * `SHRAVANA`: Shravana's 1st pada.
 */
export type AbhijitPada = 'REFUSE' | 'UTTARA_ASHADHA' | 'SHRAVANA';

/**
 * How a name written in Latin letters is read (C293).
 *
 * `REFUSE`: Refused: an English spelling is not guessed at, since its "ch" is च where IAST's is छ.
 * `IAST`: Read as IAST.
 */
export type LatinName = 'REFUSE' | 'IAST';

/**
 * Whether the deceased had the upanayana.
 *
 * `DONE`: Done.
 * `NOT_DONE`: Not yet done.
 * `NOT_PERFORMED`: Not a rite of the deceased's community: the band before it runs to marriage, or to the 16th year unmarried (*Dharmasindhu* pp. 300–301).
 */
export type Upanayana = 'DONE' | 'NOT_DONE' | 'NOT_PERFORMED';

/**
 * A day as a publisher prints it, in any calendar the SDK ships: the answer gives it in the range's.
 */
export interface PublishedDay {
  /**
   * Its calendar.
   */
  readonly calendar: Member<catalogue.Calendar>;
  /**
   * The day, 1-based.
   */
  readonly day: number;
  /**
   * The era, for a calendar that counts several.
   */
  readonly era?: EraNumber | null;
  /**
   * A leap month or day, for a calendar that marks one.
   */
  readonly leap?: catalogue.Leap | null;
  /**
   * The month, 1-based.
   */
  readonly month: number;
  /**
   * The year.
   */
  readonly year: number;
}

/**
 * A half-open interval of time, `[from, to)`.
 */
export interface Interval {
  /**
   * When it begins.
   */
  readonly from: number;
  /**
   * When it ends.
   */
  readonly to: number;
}

/**
 * The threshold table a criterion compares its measure against.
 */
export type Thresholds = ThresholdsSuryaSiddhanta | ThresholdsPtolemy | ThresholdsCustom;

/**
 * The Surya Siddhanta's degrees of time ([`Table::SURYA_SIDDHANTA`]). The tradition's combustion orbs are these same numbers. The asterisms' junction stars and the named stars have their classes (IX.12 to 15, [`Thresholds::of_star`]).
 */
export interface ThresholdsSuryaSiddhanta {
  readonly kind: 'SURYA_SIDDHANTA';
}

/**
 * Ptolemy's arcus visionis ([`Table::PTOLEMY`]).
 */
export interface ThresholdsPtolemy {
  readonly kind: 'PTOLEMY';
}

/**
 * A caller's own table.
 */
export interface ThresholdsCustom {
  readonly kind: 'CUSTOM';
}

/**
 * One term: its lord, and the degree within the sign it ends at.
 */
export interface TermEntry {
  /**
   * The degree it ends at, exclusive: a term ending at 6 holds 0° up to, and not including, 6°.
   */
  readonly end: number;
  /**
   * The planet the term belongs to.
   */
  readonly lord: Member<catalogue.Graha>;
}

export interface PartileWithin {
  /**
   * The orb.
   */
  readonly orbDeg: number;
}

export interface SiegeWithin {
  /**
   * The widest arc between Saturn and Mars that still besieges.
   */
  readonly spanDeg: number;
}

/**
 * Which drekkāṇa a graha's own is read in.
 *
 * `TAJIKA`: The Tajika one, the weekday cycle from Mars ([`drekkana_lord`]), which the 1893 print's Prashna Tantra gloss defines (n205).
 * `PARASHARI`: The Parashari one: the sign, its fifth, its ninth. The Samjna Tantra gloss's "the Moon in Cancer, in the first drekkāṇa" reads it; its other examples do not need it.
 */
export type DrekkanaReading = 'TAJIKA' | 'PARASHARI';

/**
 * Whether an enemy's sign makes a graha adhama.
 *
 * `TAJIKA`: As the definition states it, the enemy read as Tajika reads one: the sign's lord in the 1st, 4th, 7th or 10th from the graha ([`Relation::between`]), as the Panchavargiya bala and the empty road (vv. 55–56) read it. The gloss's example to v. 41 calls Mercury in Libra sama with Venus in the 4th from it.
 * `IGNORED`: Not read: no worked example needs it.
 */
export type EnemySign = 'TAJIKA' | 'IGNORED';

/**
 * Which office counts when a graha holds more than one (crux C371).
 *
 * `GLOSS`: The order the gloss's worked examples follow: debilitation, then a division it rules, then its own sign or exaltation, then an enemy's sign. A debilitated graha in its own navāṁśa is adhama (the examples to vv. 39 and 45), the Moon in Cancer in her own navāṁśa madhyama (vv. 40, 41), Venus in her own hudda in her enemy the Moon's sign madhyama (v. 38).
 * `HIGHEST`: The best office it holds.
 * `LOWEST`: The worst office it holds.
 */
export type OfficeOrder = 'GLOSS' | 'HIGHEST' | 'LOWEST';

/**
 * What the Sun's setting part is (crux C377).
 *
 * `NAVAMSHA_SIGN`: Any navāṁśa whose sign is the seventh from the sign of the Sun's navāṁśa: the gloss counts from "the navāṁśa of the sign the Sun is in", and the seventh from a sign is where it sets.
 * `NAVAMSHA_ARC`: The one navāṁśa-arc seven on from the Sun's own, 20° to 23°20′ past the start of the Sun's.
 */
export type SettingPart = 'NAVAMSHA_SIGN' | 'NAVAMSHA_ARC';

/**
 * What a dasha answers past the end of its cycle.
 *
 * `END`: No period: the cycle has ended, as the recording engine answers.
 * `REPEAT`: The cycle begins again, from its first lord and in full.
 */
export type AfterCycle = 'END' | 'REPEAT';

/**
 * How Ashtottari's eight lords share the nakshatras (crux C5).
 *
 * `THREE_EACH`: Three each from Ardra over twenty-four, the three before it outside the cycle, as the recording engine runs it.
 * `FOUR_AND_THREE`: Four and three alternately from Ardra over the twenty-eight with Abhijit, as BPHS ch. 46 vv. 17 to 20 count them.
 */
export type AshtottariGrouping = 'THREE_EACH' | 'FOUR_AND_THREE';

/**
 * A seed outside a conditional dasha's cycle.
 *
 * `WRAP_TO_START`: Wrap to the start, flagged.
 * `REJECT`: Refuse.
 */
export type SeedOverflow = 'WRAP_TO_START' | 'REJECT';

/**
 * The length of a dasha year.
 *
 * `JULIAN_365_25`: 365.25 days.
 * `SAVANA_360`: 360 days.
 * `SIDEREAL`: The sidereal year.
 * `TROPICAL`: The tropical year.
 * `LUNAR`: Twelve lunar months.
 * `NAKSHATRA_324`: 324 days.
 */
export type YearLength = 'JULIAN_365_25' | 'SAVANA_360' | 'SIDEREAL' | 'TROPICAL' | 'LUNAR' | 'NAKSHATRA_324';

/**
 * How sure the family is of an event, which weighs it.
 *
 * `CERTAIN`: Certain.
 * `PROBABLE`: Probable.
 * `UNCERTAIN`: Uncertain.
 */
export type EventConfidence = 'CERTAIN' | 'PROBABLE' | 'UNCERTAIN';

/**
 * What happened, which decides the houses and karakas a period's lord is scored against.
 *
 * `MARRIAGE`: A marriage.
 * `ENGAGEMENT`: An engagement.
 * `CHILD_BIRTH`: A child born.
 * `MISCARRIAGE`: A miscarriage.
 * `FIRST_JOB`: A first job.
 * `JOB_CHANGE`: A change of job.
 * `JOB_LOSS`: A job lost.
 * `PROMOTION`: A promotion.
 * `BUSINESS_START`: A business started.
 * `EDUCATION`: An education begun or finished.
 * `RELOCATION`: A move of home.
 * `FOREIGN_TRAVEL`: Travel abroad.
 * `PROPERTY`: Property bought.
 * `VEHICLE`: A vehicle bought.
 * `SURGERY`: Surgery.
 * `ACCIDENT`: An accident.
 * `ILLNESS`: An illness.
 * `DEATH_IN_FAMILY`: A death in the family.
 * `LITIGATION`: A lawsuit.
 * `SPIRITUAL_INITIATION`: A spiritual initiation.
 * `OTHER`: Anything else.
 */
export type LifeEventKind = 'MARRIAGE' | 'ENGAGEMENT' | 'CHILD_BIRTH' | 'MISCARRIAGE' | 'FIRST_JOB' | 'JOB_CHANGE' | 'JOB_LOSS' | 'PROMOTION' | 'BUSINESS_START' | 'EDUCATION' | 'RELOCATION' | 'FOREIGN_TRAVEL' | 'PROPERTY' | 'VEHICLE' | 'SURGERY' | 'ACCIDENT' | 'ILLNESS' | 'DEATH_IN_FAMILY' | 'LITIGATION' | 'SPIRITUAL_INITIATION' | 'OTHER';

/**
 * How finely an event's date is known, which sets the window it is fitted over.
 *
 * `DAY`: The day: a window of one day.
 * `MONTH`: The month: 31 days.
 * `YEAR`: The year: 366 days.
 */
export type DatePrecision = 'DAY' | 'MONTH' | 'YEAR';

/**
 * The women who attended, as many as the family can say.
 */
export interface Attendants {
  /**
   * How many inside the room.
   */
  readonly inside?: number | null;
  /**
   * How many outside it.
   */
  readonly outside?: number | null;
  /**
   * How many in all.
   */
  readonly total?: number | null;
}

/**
 * How much of the lamp's oil or wick was left, at the three points V.18's gloss names: a sign's start, its middle and its end.
 *
 * `FULL`: Full oil, an unburnt wick.
 * `HALF`: Half.
 * `SPENT`: No oil, a wick burnt down.
 */
export type LampLevel = 'FULL' | 'HALF' | 'SPENT';

/**
 * What came first at the birth.
 *
 * `HEAD`: The head: a sign that rises head first.
 * `FEET`: The feet: a sign that rises back first.
 * `HANDS`: The hands: Pisces, which rises both ways (the commentator's reading of V.17).
 */
export type BirthPresentation = 'HEAD' | 'FEET' | 'HANDS';

/**
 * How "the grahas between the lagna and the Moon" are counted (X19).
 *
 * `DEGREE`: By degree: a graha past the rising degree and short of the Moon's, in the zodiac's order.
 * `SIGN`: By sign: a graha in a sign after the lagna's and before the Moon's.
 */
export type BetweenBy = 'DEGREE' | 'SIGN';

/**
 * What "the Moon not seeing the lagna" asks of her aspect (X16).
 *
 * `ANY_ASPECT`: Any aspect at all, a quarter or more: BJ II.13 gives every graha its quarter, half, three-quarter and full aspects, and V.1 says only "not seeing". The Moon in the lagna's own sign does not see it.
 * `FULL`: Only the full aspect, from the 7th.
 */
export type MoonSees = 'ANY_ASPECT' | 'FULL';

/**
 * Which half of the attendants V.22 puts outside the room.
 *
 * `VISIBLE`: The visible half outside, the invisible inside: Varahamihira's own, which the commentator says his *Swalpa Jataka* confirms.
 * `INVISIBLE`: The reverse, which V.22 gives as some others'.
 */
export type OutsideHalf = 'VISIBLE' | 'INVISIBLE';

/**
 * Which reading of V.17's presentation is asked (X18).
 *
 * `RISING_SIGN`: As the rising sign rises (BJ I.10): head first, back first, or Pisces both ways, which the commentator reads as the hands.
 * `LAGNA_LORD_MOTION`: By the lagna lord's motion: direct, a natural birth, head first; retrograde, an irregular one (the reading Manittha supports).
 */
export type PresentationBy = 'RISING_SIGN' | 'LAGNA_LORD_MOTION';

/**
 * Which houses are "fallen from the 10th" for the Sun in V.1 (X17).
 *
 * `NINTH_OR_EIGHTH`: The 9th or the 8th: Iyer's 1885 translation, following Bhattotpala, the houses the Sun falls through after culminating.
 * `EITHER_SIDE`: The 8th, 9th, 11th or 12th: Vijnanananda's 1912 gloss of *madhyād bhraṣṭe*, fallen from the 10th either way.
 */
export type SunFallen = 'NINTH_OR_EIGHTH' | 'EITHER_SIDE';

/**
 * How BJ IV.21's count runs from the Moon's dvadashamsha at conception to the sign the Moon holds at birth (X11).
 *
 * `NEXT_AFTER_DVADASHAMSHA`: From the sign after the dvadashamsha's, as many signs as its number: Bhattotpala's *sādhvī vyākhyā* after Garga, and Iyer.
 * `FROM_MOON_SIGN`: The dvadashamsha's own sign, counted from the Moon's: the 1912 main text, after Gargi.
 * `FROM_ARIES`: As many signs from Aries: the view Bhattotpala gives to "some", after Saravali.
 */
export type ConceptionCount = 'NEXT_AFTER_DVADASHAMSHA' | 'FROM_MOON_SIGN' | 'FROM_ARIES';

/**
 * What Pisces is, which the prints class two ways.
 *
 * `EITHER`: Strong by day or by night, so a birth may be either (1912).
 * `DAY`: A day sign (Iyer's BJ I.10 note).
 */
export type ConceptionPisces = 'EITHER' | 'DAY';

/**
 * What of the conception's rising point BJ IV.21 classes as a day or a night sign.
 *
 * `SIGN`: The rising sign: the verse and the 1912 main text.
 * `NAVAMSHA`: The rising navamsha: Iyer, the 1912 notes, Bhattotpala's "division".
 */
export type ConceptionRising = 'SIGN' | 'NAVAMSHA';

/**
 * How v. 28's "the invisible half" is read.
 *
 * `BY_LONGITUDE`: The half-circle ahead of the lagna's degree: Jha's "within the six signs ahead of the lagna", by longitude.
 * `BY_SIGN`: The 1st to the 6th signs from the lagna's.
 */
export type InvisibleHalf = 'BY_LONGITUDE' | 'BY_SIGN';

/**
 * Which end of Saturn's eighth Mandi is, for the conception: the start by default, as Jha (X5 decides the end for the purifier, after the Subodhini's gloss).
 *
 * `START`: The start of Saturn's eighth (Jha ch. 3 v. 70).
 * `END`: Its end (the Subodhini's Gulika).
 */
export type NishekaMandi = 'START' | 'END';

/**
 * How long the "month" v. 28 reads a sign as.
 *
 * `THIRTY_DAYS`: Thirty days, so a degree is a day and the arc is the days: Jha's units, "months, days, ghatis, palas".
 * `SOLAR`: A twelfth of the sidereal year.
 * `SYNODIC`: A synodic month.
 */
export type NishekaMonth = 'THIRTY_DAYS' | 'SOLAR' | 'SYNODIC';

/**
 * Which point v. 27's "the lagna to the 9th bhava" measures to.
 *
 * `SRIPATI`: Sripati's mid-point of the 9th: Jha's bhava table, and the figure his worked example uses.
 * `WHOLE_SIGN`: The start of the 9th sign from the lagna's.
 * `EQUAL`: Eight signs past the lagna's degree.
 */
export type NinthBhava = 'SRIPATI' | 'WHOLE_SIGN' | 'EQUAL';

/**
 * Which point of Saturn v. 27's "where Saturn stands" measures from.
 *
 * `LONGITUDE`: Saturn's longitude, as Jha's example takes it.
 * `BHAVA_MADHYA`: The Sripati mid-point of the bhava Saturn stands in, a literal reading of *yasmin bhāve sthitaḥ* no worked example takes.
 */
export type SaturnTerm = 'LONGITUDE' | 'BHAVA_MADHYA';

/**
 * How a house is counted from the lagna to a point.
 *
 * `SIGN`: By sign from the lagna's sign. Jha's worked example forces it: its pranapada stands 23°09′ past the lagna and is printed in the 2nd.
 * `SRIPATI_BHAVA`: By Sripati's bhava, the sandhis halfway between the mid-points.
 */
export type HouseCount = 'SIGN' | 'SRIPATI_BHAVA';

/**
 * How the pranapada is reckoned (X2, X3).
 *
 * `VERSE`: The verse: the Sun's longitude, shifted by v. 74 to itself, its 9th or its 5th for a movable, fixed or dual sign, then a sign every fifteen palas since sunrise, 300° an hour.
 * `PRINTED_EXAMPLE`: The reading that reproduces the gloss's printed answer (p. 13): the signs taken mod 15 and counted inclusively from the movable sign of the Sun's triplicity, two degrees for each left-over pala.
 * `SDK_POINT`: The SDK's `points::lagna::pranapada`, settled against the conformance corpus at 60° an hour.
 */
export type PranapadaRule = 'VERSE' | 'PRINTED_EXAMPLE' | 'SDK_POINT';

/**
 * Which end of Saturn's eighth is Gulika (X5).
 *
 * `END`: Its end, where the gloss's multipliers put it (16;37 ghatis in its worked case).
 * `START`: Its start, the SDK's `Gulika` point.
 */
export type GulikaAt = 'END' | 'START';

/**
 * When v. 76's extension of Gulika (its 7th, its navamsha and that navamsha's 7th) counts toward a verdict (X7).
 *
 * `WHEN_TWO_FAIL`: Counted when neither the pranapada nor the Moon holds.
 * `ALWAYS`: Counted at every instant, without precedence.
 * `NEVER`: Not judged: Gulika purifies by its own sign alone.
 */
export type GulikaExtension = 'WHEN_TWO_FAIL' | 'ALWAYS' | 'NEVER';

/**
 * The species vv. 77–78 assign the twelve houses to.
 *
 * `HUMAN`: A human: the sign and its trines, houses 1, 5 and 9 (v. 77).
 * `BEAST`: A beast: houses 2, 6 and 10 (v. 77).
 * `BIRD`: A bird: houses 3, 7 and 11 (v. 78).
 * `CREEPER`: A creeping or water creature: houses 4, 8 and 12 (v. 78).
 */
export type RectificationSpecies = 'HUMAN' | 'BEAST' | 'BIRD' | 'CREEPER';

/**
 * Whether a lagna no purifier holds is removed or only weighed (X8).
 *
 * `BAR`: Removed: v. 75 calls it "the birth of a plant".
 * `WEIGHT`: Kept, its verdict saying it is impure.
 */
export type PurifyAs = 'BAR' | 'WEIGHT';

/**
 * Whose devotee the Sun with Ketu makes (C354). The 1899 and 1923 prints give vv. 70–71 with their fruits exchanged and read *ravi-bhakti*; the recension and Jaimini's *Upadeśa Sūtras* read Śiva for the Sun and Gaurī for the Moon.
 *
 * `SHIVA`: Śiva, the recension's *śiva-bhakti*; the default.
 * `SURYA`: Sūrya, the prints' *ravi-bhakti*.
 */
export type SunWithKetu = 'SHIVA' | 'SURYA';

/**
 * How a graha's summary nature is derived from its lordships.
 *
 * `LAGHU_PARASHARI`: *Laghu Parashari* vv. 6 to 20 and BPHS ch. 13 vv. 1 to 13: the lords of 3, 6 and 11 are evil, the 8th lord is not good unless it is the lagna lord or a luminary, a kendra lord loses its natural nature, the 2nd and 12th act by association, and a trikona lord is good whatever else it owns (C329, C330).
 * `BASELINE`: The baseline engine's: the lords of 1, 5 and 9 good, the lords of 6, 8 and 12 bad unless they also own a trikona, and a yogakaraka any other kendra lord that owns a trikona. No text read gives the 12th lord as evil or exempts no one from the 8th (C331).
 */
export type FunctionalScheme = 'LAGHU_PARASHARI' | 'BASELINE';

/**
 * Which text's ṛk is given for Rahu. The two texts agree for the other eight grahas (C343).
 *
 * `BPHS`: BPHS 84.18: *kayā naś citra*.
 * `YAJNAVALKYA`: Yājñavalkya I.301: *kāṇḍāt*.
 */
export type RikSource = 'BPHS' | 'YAJNAVALKYA';

/**
 * Which node's side the seven stand on.
 *
 * `rahu`: Between Rahu and Ketu in the zodiac's own direction: the ascending arc.
 * `ketu`: Between Ketu and Rahu: the descending arc.
 */
export type NodeSide = 'rahu' | 'ketu';

/**
 * A chara karaka, by its abbreviation.
 *
 * `AK`: 
 * `AmK`: 
 * `BK`: 
 * `MK`: 
 * `PK`: 
 * `GK`: 
 * `DK`: 
 * `PiK`:
 */
export type Karaka = 'AK' | 'AmK' | 'BK' | 'MK' | 'PK' | 'GK' | 'DK' | 'PiK';

/**
 * Which eclipse.
 *
 * `solar`: Of the Sun.
 * `lunar`: Of the Moon.
 * `any`: Either.
 */
export type EclipseKind = 'solar' | 'lunar' | 'any';

/**
 * A class of grahas, which the evaluator resolves once a chart: what an `any-…` subject stands for, and what a `planet-is` condition asks a body belongs to. One place names each class, so a new one is one arm here and one list in the evaluator, not an arm at every site that reads a subject.
 *
 * `benefic`: The benefics, under the readings.
 * `malefic`: The malefics, under the readings.
 * `maraka`: The marakas.
 */
export type GrahaClass = 'benefic' | 'malefic' | 'maraka';

/**
 * A natural relationship between two grahas.
 *
 * `friend`: A friend.
 * `neutral`: Neither friend nor enemy.
 * `enemy`: An enemy.
 */
export type Relation = 'friend' | 'neutral' | 'enemy';

/**
 * Which end of a limb a condition measures.
 *
 * `first`: Its beginning: so many ghatikas after it started.
 * `last`: Its end: so many ghatikas before it ends.
 */
export type Edge = 'first' | 'last';

/**
 * Which limb a condition measures.
 *
 * `tithi`: The tithi.
 * `nakshatra`: The Moon's nakshatra.
 * `lagna`: The rising sign.
 * `night`: The night, sunset to sunrise, whose first and last ghatikas are the twilights.
 */
export type Limb = 'tithi' | 'nakshatra' | 'lagna' | 'night';

/**
 * Where an intervention comes from, and what obstructs it (BPHS ch. 31 v. 9's table: 4 2 11 5 over 10 12 3 9).
 *
 * `second`: The second, obstructed from the twelfth.
 * `fourth`: The fourth, obstructed from the tenth.
 * `fifth`: The fifth, obstructed from the ninth.
 * `eleventh`: The eleventh, obstructed from the third.
 */
export type ArgalaPlace = 'second' | 'fourth' | 'fifth' | 'eleventh';

/**
 * The unit a span is counted in, as the verse counts it.
 *
 * `days`: Days.
 * `months`: Months.
 * `years`: Years.
 */
export type Unit = 'days' | 'months' | 'years';

/**
 * A class of life, BPHS ch. 43 vv. 52 to 54, from the shortest up.
 *
 * `balarishta`: Death in infancy: eight years.
 * `yogarishta`: An evil from a yoga: twenty years.
 * `short`: Short life, alpayu: thirty-two years.
 * `medium`: Medium life, madhyayu: sixty-four years.
 * `long`: Long life, purnayu: a hundred and twenty years.
 * `divine`: A super-natural life: a thousand years.
 * `unlimited`: Illimitable longevity, amitayu, which the verse gives no number.
 */
export type LifeClass = 'balarishta' | 'yogarishta' | 'short' | 'medium' | 'long' | 'divine' | 'unlimited';

/**
 * What a pair less than a degree **past** is doing — the one place the source's two accounts of a pair disagree.
 *
 * `POORNA`: **Poorna**, the default: the table's two rows read so that they interlock — a pair within a degree either way is complete, and Ishrafa begins at exactly the degree the table names. The only reading under which the table's own threshold does any work.
 * `ISHRAFA`: **Ishrafa**: the chapter's prose, where anything past is drawing away however near. What this module shipped before Table X-3 was read.
 * `NONE`: **Nothing**: the table at its narrowest, where Poorna only ever narrows Vartamana and the band belongs to no yoga. Carried because it is a defensible reading of the printed words, though it leaves those 934 pairs saying nothing at all.
 */
export type SubDegree = 'POORNA' | 'ISHRAFA' | 'NONE';

/**
 * A year in an era, for presentation.
 */
export interface EraNumber {
  /**
   * The era.
   */
  readonly era: Member<catalogue.Era>;
  /**
   * The year in it, 1-based.
   */
  readonly year: number;
}
